/* ============================================================
   FORMATTERS
   ============================================================ */

const formatFR = {
  num1: (n) => Number(n).toFixed(1).replace('.', ','),
  num2: (n) => Number(n).toFixed(2).replace('.', ','),
  int:  (n) => Math.round(Number(n)).toLocaleString('fr-FR').replace(/,/g, '\u202F'),
};
const fmtVal = (kpi) => formatFR[kpi.fmt || 'num1'](kpi.value);
const fmtPct = (curr, prev, inverse = false) => {
  const raw = ((curr - prev) / prev) * 100;
  const delta = inverse ? -raw : raw;
  return { value: delta, label: (delta >= 0 ? '+' : '') + delta.toFixed(1).replace('.', ',') + '%' };
};

