function KPICard({ kpi, icon, accent = '#D9A84F', delay = 0 }) {
  const delta = fmtPct(kpi.value, kpi.prev, kpi.inverse);
  const positive = delta.value >= 0;
  const targetPct = kpi.inverse
    ? Math.min(100, Math.max(0, ((kpi.prev - kpi.value) / (kpi.prev - kpi.target)) * 100))
    : Math.min(100, Math.max(0, (kpi.value / kpi.target) * 100));

  return (
    <div className={`gradient-border p-5 fade-up`} style={{ animationDelay: `${delay}s` }}>
      <div className="flex items-start justify-between mb-4">
        <div className="w-10 h-10 rounded-lg flex items-center justify-center" style={{ background: accent + '1A', color: accent }}>
          {icon}
        </div>
        <div className={`text-xs font-semibold px-2 py-1 rounded-full flex items-center gap-1 ${positive ? 'bg-emerald-500/10 text-emerald-400' : 'bg-rose-500/10 text-rose-400'}`}>
          <svg className="w-3 h-3" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5">
            <path d={positive ? 'M7 17L17 7M7 7h10v10' : 'M17 7L7 17M17 17H7V7'}/>
          </svg>
          {delta.label}
        </div>
      </div>
      <div className="text-[.7rem] tracking-[.12em] uppercase text-white/50 font-semibold mb-1">{kpi.label}</div>
      <div className="flex items-baseline gap-1.5 mb-3">
        <span className="font-display text-3xl font-semibold text-white tracking-tight">{fmtVal(kpi)}</span>
        <span className="text-sm text-white/55 font-medium">{kpi.unit}</span>
      </div>
      <div className="flex items-center justify-between text-[.68rem] text-white/55 mb-1.5">
        <span>Objectif {kpi.fmt === 'int' ? formatFR.int(kpi.target) : formatFR.num1(kpi.target)} {kpi.unit}</span>
        <span className="font-mono font-semibold" style={{ color: accent }}>{targetPct.toFixed(0)}%</span>
      </div>
      <div className="h-1.5 rounded-full bg-white/5 overflow-hidden">
        <div className="h-full rounded-full transition-all" style={{ width: `${targetPct}%`, background: `linear-gradient(90deg, ${accent}, ${accent}cc)` }}></div>
      </div>
    </div>
  );
}

