function CustomTooltip({ active, payload, label, unit = '' }) {
  if (!active || !payload || !payload.length) return null;
  return (
    <div className="bg-navy-2 border border-gold/30 rounded-lg p-3 shadow-2xl text-xs min-w-[180px]">
      <div className="font-display font-semibold text-white mb-2 text-[.82rem]">{label}</div>
      {payload.map((p, i) => (
        <div key={i} className="flex items-center justify-between gap-3 py-0.5">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 rounded-full" style={{ background: p.color }}></span>
            <span className="text-white/70 capitalize">{p.name}</span>
          </div>
          <span className="font-mono font-semibold text-white">
            {typeof p.value === 'number' ? p.value.toLocaleString('fr-FR', { maximumFractionDigits: 1 }) : p.value} {unit}
          </span>
        </div>
      ))}
    </div>
  );
}

