function App() {
  const [selectedPoles, setSelectedPoles] = useState(new Set(POLES.map(p => p.id)));
  const [year, setYear] = useState(2026);
  const [period, setPeriod] = useState('YTD');
  const [refreshing, setRefreshing] = useState(false);
  const [currentDate, setCurrentDate] = useState('');

  useEffect(() => {
    const d = new Date();
    setCurrentDate(d.toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' }) + ' · ' + d.toLocaleTimeString('fr-FR', { hour: '2-digit', minute: '2-digit' }));
  }, []);

  const togglePole = (id) => {
    setSelectedPoles(prev => {
      if (id === 'all') {
        return prev.size === POLES.length ? new Set() : new Set(POLES.map(p => p.id));
      }
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const onRefresh = () => {
    setRefreshing(true);
    setTimeout(() => setRefreshing(false), 1200);
  };

  const onExport = () => {
    const rows = [['Projet', 'Pôle', 'Stage', 'Pays', 'CAPEX (M$)', 'Risque', 'Statut']];
    DEAL_FLOW.forEach(d => {
      const pole = POLES.find(p => p.id === d.pole);
      rows.push([d.project, pole.short, d.stage, d.country, d.capex, d.risk, d.status]);
    });
    const csv = rows.map(r => r.map(c => `"${c}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'enertchad-deal-flow-q1-2026.csv';
    a.click(); URL.revokeObjectURL(url);
  };

  return (
    <div className="min-h-screen">
      <Topbar currentDate={currentDate} onExport={onExport} onRefresh={onRefresh} refreshing={refreshing} />

      <FilterBar
        selectedPoles={selectedPoles}
        onTogglePole={togglePole}
        year={year}
        onYearChange={setYear}
        period={period}
        onPeriodChange={setPeriod}
      />

      <main id="main-content" tabIndex={-1} className="max-w-[1600px] mx-auto px-6 py-6 space-y-6">

        {/* Executive summary banner */}
        <div className="gradient-border p-5 flex flex-wrap items-center justify-between gap-4 fade-up">
          <div>
            <div className="text-[.68rem] font-semibold tracking-[.18em] uppercase text-gold mb-1">Performance Q1 2026</div>
            <h2 className="font-display text-xl text-white font-semibold tracking-tight">
              Production <span className="text-gold">+4,0%</span> vs Q1 2025 · Objectif annuel consolidé en bonne voie
            </h2>
          </div>
          <div className="flex items-center gap-6">
            <div className="text-center">
              <div className="font-display text-2xl font-semibold text-white">6</div>
              <div className="text-[.68rem] text-white/50 uppercase tracking-wider">pôles actifs</div>
            </div>
            <div className="w-px h-8 bg-white/10"></div>
            <div className="text-center">
              <div className="font-display text-2xl font-semibold text-emerald-400">12</div>
              <div className="text-[.68rem] text-white/50 uppercase tracking-wider">projets en cours</div>
            </div>
            <div className="w-px h-8 bg-white/10"></div>
            <div className="text-center">
              <div className="font-display text-2xl font-semibold text-gold">1 240</div>
              <div className="text-[.68rem] text-white/50 uppercase tracking-wider">collaborateurs</div>
            </div>
          </div>
        </div>

        {/* KPI Grid */}
        <section className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <KPICard kpi={KPIS.production}   icon={ICONS.oil}     accent="#D9A84F" delay={0.02} />
          <KPICard kpi={KPIS.revenue}      icon={ICONS.money}   accent="#10B981" delay={0.04} />
          <KPICard kpi={KPIS.capex}        icon={ICONS.trend}   accent="#2C7AE0" delay={0.06} />
          <KPICard kpi={KPIS.ebitda_mgn}   icon={ICONS.factory} accent="#BE185D" delay={0.08} />
          <KPICard kpi={KPIS.hse_trir}     icon={ICONS.shield}  accent="#F59E0B" delay={0.10} />
          <KPICard kpi={KPIS.local_content}icon={ICONS.users}   accent="#8B5CF6" delay={0.12} />
          <KPICard kpi={KPIS.ghg_int}      icon={ICONS.leaf}    accent="#0891B2" delay={0.14} />
          <KPICard kpi={KPIS.transmission} icon={ICONS.bolt}    accent="#E8C36A" delay={0.16} />
        </section>

        {/* Main charts grid */}
        <section className="grid grid-cols-1 xl:grid-cols-3 gap-5">
          <div className="xl:col-span-2"><ProductionChart selectedPoles={selectedPoles} /></div>
          <PoleMixChart selectedPoles={selectedPoles} />
          <CapexChart selectedPoles={selectedPoles} />
          <ESGRadar />
          <SitesCard />
        </section>

        {/* Deal flow */}
        <section className="grid grid-cols-1 gap-5">
          <DealFlowTable selectedPoles={selectedPoles} />
        </section>

        {/* Footer strip */}
        <footer className="pt-6 pb-2 flex flex-wrap items-center justify-between gap-3 text-[.72rem] text-white/55 border-t border-white/5">
          <div>Source : EnerTchad Groupe SA/CA · Données internes · Conforme IFRS · Transparence ITIE</div>
          <div className="flex items-center gap-4">
            <span>Dashboard v2.0 · Prototype exécutif</span>
            <span className="font-mono text-gold/70">2026 Q1</span>
          </div>
        </footer>
      </main>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(<App />);